state_dir=Path('voting-map');state_dir.mkdir(exist_ok=True)
for code,(name,slug) in STATE_META.items():
    url=f'{SITE}/voting-map/{slug}'
    page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{name} Voting Information & 2026 Live Map</title><meta name="description" content="Use the {name} 2026 voting map, anonymous check-in totals, official polling-place and registration resources, transportation planning, and voter-help links."><link rel="canonical" href="{url}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="stylesheet" href="/styles.css"><style>body{{background:#07110d;color:#fff}}.state-page{{width:min(1000px,92vw);margin:auto;padding:60px 0}}.state-page h1{{font-size:clamp(52px,8vw,90px);line-height:.9}}.state-grid{{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:28px 0}}.state-card{{border:1px solid #345044;background:#0d1b15;padding:20px}}.state-card p{{color:#c8d2cc;line-height:1.55}}.state-card a{{color:#50ef9b}}@media(max-width:700px){{.state-grid{{grid-template-columns:1fr}}}}</style><script type="application/ld+json">{{"@context":"https://schema.org","@type":"WebPage","name":"{name} Voting Information & 2026 Live Map","url":"{url}","description":"Nonpartisan {name} voting resources for the 2026 election."}}</script></head><body><main class="state-page"><div class="eyebrow green">2026 STATE VOTING RESOURCE</div><h1>{name.upper()}.</h1><p>Use this page as a direct starting point for {name}. Anonymous check-ins are self-reported and are not official turnout. Official election information stays with election authorities.</p><div class="state-grid"><section class="state-card"><h2>LIVE {code} MAP</h2><p>Open the national interactive map already focused on {name}, including public state totals and district breakdowns that meet the privacy threshold.</p><a class="button primary" href="/voting-map?state={code}">OPEN {name.upper()} MAP →</a></section><section class="state-card"><h2>OFFICIAL VOTING INFO</h2><p>Verify registration, deadlines, voting options and your address-specific polling place through official sources.</p><a href="https://www.eac.gov/{slug}-voter-info" target="_blank" rel="noopener">EAC {name} voter guide ↗</a><br><br><a href="https://vote.gov/register" target="_blank" rel="noopener">Vote.gov registration ↗</a></section><section class="state-card"><h2>TRANSPORTATION</h2><p>Compare rideshare, transit, paratransit, taxi, driving, walking and local transportation resources. You make the arrangement directly.</p><a href="/rides-to-polls?state={code}">Plan a ride in {name} →</a></section><section class="state-card"><h2>VOTER HELP</h2><p>Election Protection and official voter-help resources are available if you encounter a problem or need assistance.</p><a href="/voter-help?state={code}">Open voter help →</a></section></div><p><a href="/voting-map">← Back to national voting map</a></p></main></body></html>'''
    (state_dir/f'{slug}.html').write_text(page)

