sp=Path('sitemap.xml')
text=sp.read_text()
for code,(name,slug) in STATE_META.items():
    loc=f'{SITE}/voting-map/{slug}'
    if loc not in text:
        text=text.replace('</urlset>',f'  <url>\n    <loc>{loc}</loc>\n    <lastmod>{TODAY}</lastmod>\n    <changefreq>daily</changefreq>\n    <priority>0.82</priority>\n  </url>\n</urlset>')
text=text.replace('<lastmod>2026-09-08</lastmod>',f'<lastmod>{TODAY}</lastmod>')
sp.write_text(text)
